/// JSX/DSL shorthand to convert a `0xRRGGBBAA` hex literal into `[r, g, b, a]`.
#[inline]
pub fn hex(rgba: u32) -> Color {
    let r = ((rgba >> 24) & 0xFF) as u8;
    let g = ((rgba >> 16) & 0xFF) as u8;
    let b = ((rgba >> 8) & 0xFF) as u8;
    let a = (rgba & 0xFF) as u8;
    return [r, g, b, a];
}
